  "kerf/box": "// kerf/box: finger-jointed boxes.\n// Copyright (c) 2026 MyLaserTools. AGPL-3.0-only or MyLaserTools commercial licence.\n\n// Box from its outer size [width, depth, height] in the current material.\n// Edges pair \"out\" with \"in\", and the bottom owns every bottom corner,\n// so the six panels interlock without gaps.\nmodule box(size, lid = false, finger = undef) {\n  w = size[0];\n  d = size[1];\n  h = size[2];\n  t = $thickness;\n  top = lid ? \"in\" : \"flat\";\n  part(\"bottom\", at = [0, 0, 0]) finger_rect([w, d], \"out\", finger = finger);\n  if (lid) part(\"lid\", at = [0, 0, h - t]) finger_rect([w, d], \"out\", finger = finger);\n  part(\"front\", at = [0, t, 0], rotate = [90, 0, 0])\n    finger_rect([w, h], [\"in\", \"out\", top, \"out\"], finger = finger);\n  part(\"back\", at = [0, d, 0], rotate = [90, 0, 0])\n    finger_rect([w, h], [\"in\", \"out\", top, \"out\"], finger = finger);\n  part(\"left\", rotate = [90, 0, 90])\n    finger_rect([d, h], [\"in\", \"in\", top, \"in\"], finger = finger);\n  part(\"right\", at = [w - t, 0, 0], rotate = [90, 0, 90])\n    finger_rect([d, h], [\"in\", \"in\", top, \"in\"], finger = finger);\n}\n\n// Divider that slides between two walls: tabs on both sides drop into\n// finger_holes() cut in the walls.\nmodule divider(size, finger = undef) {\n  finger_rect(size, [\"flat\", \"out\", \"flat\", \"out\"], finger = finger);\n}\n"
